CREATE TABLE supplier_return (
 id UUID PRIMARY KEY,tenant_id UUID NOT NULL,receipt_id UUID NOT NULL,branch_id UUID NOT NULL,supplier_id UUID NOT NULL,
 amount NUMERIC(19,2) NOT NULL CHECK(amount>=0),debt_credit NUMERIC(19,2) NOT NULL CHECK(debt_credit>=0),supplier_credit NUMERIC(19,2) NOT NULL CHECK(supplier_credit>=0),
 note VARCHAR(500) NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,id,receipt_id),FOREIGN KEY(tenant_id,receipt_id) REFERENCES purchase_receipt(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id),FOREIGN KEY(tenant_id,supplier_id) REFERENCES supplier(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES app_user(tenant_id,id));
CREATE TABLE supplier_return_line(tenant_id UUID NOT NULL,return_id UUID NOT NULL,receipt_id UUID NOT NULL,order_line_id UUID NOT NULL,quantity NUMERIC(19,6) NOT NULL CHECK(quantity>0),amount NUMERIC(19,2) NOT NULL CHECK(amount>=0),operation_id UUID NOT NULL,PRIMARY KEY(tenant_id,return_id,order_line_id),FOREIGN KEY(tenant_id,return_id,receipt_id) REFERENCES supplier_return(tenant_id,id,receipt_id),FOREIGN KEY(tenant_id,receipt_id,order_line_id) REFERENCES purchase_receipt_line(tenant_id,receipt_id,order_line_id),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,operation_id) REFERENCES stock_operation(tenant_id,id));
CREATE TABLE supplier_return_debt_credit(tenant_id UUID NOT NULL,return_id UUID NOT NULL,payable_id UUID NOT NULL,amount NUMERIC(19,2) NOT NULL CHECK(amount>0),PRIMARY KEY(tenant_id,return_id,payable_id),FOREIGN KEY(tenant_id,return_id) REFERENCES supplier_return(tenant_id,id),FOREIGN KEY(tenant_id,payable_id) REFERENCES payable(tenant_id,id));
CREATE INDEX ix_supplier_return_receipt ON supplier_return(tenant_id,receipt_id);
